from html import escape as e
from urllib.parse import urlencode,urlsplit

STYLE='''*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#07060d;color:#eeeaf5;font:14px/1.6 "Segoe UI",sans-serif;--accent:#bb8aff}a{color:inherit;text-decoration:none}button,input,select{font:inherit}button,a,select{cursor:default}header{display:flex;align-items:center;gap:34px;padding:25px 40px;border-bottom:1px solid #201a2c}.brand{font-weight:600;font-size:19px;white-space:nowrap}.mark{display:inline-block;color:#b580fa;font-size:29px;font-weight:800;font-style:italic;margin-right:11px;line-height:1}header aside{margin-left:auto;color:#a69cb6;font-size:12px;display:flex;gap:24px}.search{position:relative;width:min(660px,100%)}form{display:flex;align-items:center;border:1px solid #40344e;background:#0b0911;border-radius:28px;padding:4px 8px 4px 20px;gap:12px}form:focus-within{border-color:#9c62df;box-shadow:0 0 0 3px #9c62df0b}input{color:#f3eefb;border:0;background:none;outline:0;min-width:0;flex:1;padding:9px 0;font-size:15px}button{background:none;border:0;color:#c89bf9;padding:6px;border-radius:50%;display:grid;place-items:center;width:36px;height:36px}button:hover{background:#251a32}svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.7}main{max-width:1150px;margin:0 auto;padding:30px 42px 90px}.hero{min-height:calc(100vh - 190px);display:flex;align-items:center;justify-content:center;flex-direction:column;padding-bottom:100px}.hero .mark{font-size:70px;margin:0}.hero h1{font-size:38px;font-weight:550;margin:8px 0}.hero p{color:#a69bb8;margin:0 0 32px;font-size:16px}.hint{font-size:12px;color:#82768f;margin-top:18px}.filters{display:flex;align-items:center;gap:25px;border-bottom:1px solid #241c30;padding:0 0 14px;margin-bottom:20px}.filters a{color:#a69bb7;font-size:13px}.filters a.active{color:#e4d1ff;border-bottom:2px solid #ac71f3;padding-bottom:15px}.filters select{margin-left:auto;background:#0d0a13;color:#b5a9c4;border:1px solid #30233d;border-radius:8px;padding:5px 10px;font-size:12px}.summary{color:#8c809b;font-size:12px;margin:0 0 28px}.results{max-width:720px}.result{margin:0 0 30px}.source{display:flex;align-items:center;gap:10px;color:#d5cddd;font-size:12px}.initial{background:#1b1427;border:1px solid #332441;color:#ba91e7;border-radius:8px;width:29px;height:29px;display:grid;place-items:center;font-weight:600}.url{color:#887b96;max-width:620px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px}.result h2{font-size:20px;font-weight:500;line-height:1.4;color:var(--accent);margin:8px 0 5px}.result h2 a:hover{text-decoration:underline}.result p{font-size:13px;color:#b3a8bf;line-height:1.8;margin:0}.source small{font-size:10px;color:#80728e;margin-left:7px}.empty{padding:35px 0;color:#aaa0b8}.empty h2{color:#e6dcee;font-size:20px;font-weight:500}.pages{display:flex;gap:22px;color:#c89bf9;margin-top:25px}footer{position:fixed;bottom:0;left:0;right:0;background:#09070eee;border-top:1px solid #211a2a;padding:14px 40px;color:#887d97;display:flex;justify-content:space-between;font-size:11px;backdrop-filter:blur(12px)}.suggestions{position:absolute;left:0;right:0;top:58px;background:#100c18;border:1px solid #3b2a4a;border-radius:14px;overflow:hidden;z-index:4;box-shadow:0 12px 35px #0008}.suggestions a{display:block;padding:10px 18px;color:#c8b9d9;font-size:13px}.suggestions a:hover,.suggestions a:focus{background:#231532;outline:0}.prose{max-width:700px}.prose h1{font-size:28px;font-weight:500}.prose p{color:#b5a8c2}.tag{padding:3px 10px;border:1px solid #30223f;border-radius:20px;color:#9f88b9;font-size:11px}@media(max-width:760px){header{padding:18px;flex-wrap:wrap;gap:15px}header aside{display:none}main{padding:25px 20px 90px}.hero h1{font-size:30px}header .search{order:3;width:100%}.filters{gap:18px}.result h2{font-size:18px}footer{padding:12px 20px}footer span:last-child{display:none}}'''
SCRIPT='''(()=>{const q=document.querySelector('input[name=q]'),list=document.querySelector('.suggestions');if(!q||!list)return;let timer,controller;const hide=()=>list.replaceChildren();q.addEventListener('input',()=>{clearTimeout(timer);controller?.abort();hide();if(q.value.trim().length<2)return;timer=setTimeout(async()=>{controller=new AbortController();try{const response=await fetch('suggest?q='+encodeURIComponent(q.value),{signal:controller.signal});if(!response.ok)return;const values=await response.json();hide();for(const value of values){const a=document.createElement('a');a.textContent=value;a.href='search?q='+encodeURIComponent(value);list.append(a);}}catch{}},110)});q.addEventListener('keydown',e=>{if(e.key==='Escape')hide();if(e.key==='ArrowDown'&&list.firstChild){e.preventDefault();list.firstChild.focus();}});document.addEventListener('click',e=>{if(!e.target.closest('.search'))hide()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();q.focus();}});document.querySelector('select')?.addEventListener('change',e=>{const url=new URL(location.href);url.searchParams.set('order',e.target.value);url.searchParams.delete('page');location.href=url;});})();'''
MAGNIFY='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg>'
MARK='<svg viewBox="0 0 200 120" aria-hidden="true"><path d="M4 108C21 77 44 13 72 9c32-5 36 60 49 58 14-3 47-54 75-60-24 39-48 100-79 101-31 1-31-60-44-61C59 46 36 91 4 108Z"/></svg>'
STYLE+='.suggestions:empty{display:none}.mark svg{width:30px;height:25px;fill:#ae79f5;stroke:none;vertical-align:middle}.hero .mark svg{width:100px;height:74px}'

def form(query=''):
    return '<div class="search"><form action="search" method="get">'+MAGNIFY+'<input name="q" maxlength="300" aria-label="Rechercher dans l’index Nova" placeholder="Rechercher avec Nova…" value="'+e(query,quote=True)+'" autocomplete="off"><button aria-label="Lancer la recherche">'+MAGNIFY+'</button></form><div class="suggestions" role="list"></div></div>'

def page(query,found,stats,kind='all',order='relevance',about=False):
    remote=stats.get('provider')=='Brave'
    brand='<a class="brand" href="./"><span class="mark">'+MARK+'</span>Nova Search</a>'
    header='<header>'+brand+(form(query) if query and not about else '')+'<aside><a href="about">À propos</a><span class="tag">'+('Recherche Web' if remote else 'Index Nova')+'</span></aside></header>'
    if about:
        content='''<main class="prose"><h1>Un moteur à nous.</h1><p>Nova Search interroge son propre index. Vos recherches ne sont pas transmises à Google ni à une API de recherche externe.</p><p>L’index initial est un petit catalogue de sites sélectionnés, avec des descriptions rédigées pour Nova. Les pages explorées par NovaBot sont indiquées séparément. Les résultats proviennent uniquement de cet index ; sa couverture est encore limitée.</p><p>NovaBot peut étendre cet index depuis une liste de sites HTTPS, avec contrôle de robots.txt, des directives noindex et un rythme limité. Les pages privées et les sessions de navigation ne sont pas explorées.</p><p>Aucun journal de requêtes, cookie publicitaire ou script tiers n’est utilisé par ce service. Cliquer sur un résultat ouvre le site concerné, qui applique sa propre politique.</p><a href="./">← Revenir à la recherche</a></main>'''
        if remote:content='<main class="prose"><h1>Nova, ouvert sur le Web.</h1><p>Nova fournit l’interface de recherche. Les résultats Web sont fournis par Brave Search API, qui reçoit la requête lorsque vous lancez une recherche. La clé API reste sur le serveur Nova.</p><p>Nova ne conserve pas les résultats Brave dans son index local et ne journalise pas les requêtes. Un compteur quotidien sans contenu de recherche limite les appels payants. Les règles du fournisseur et celles des sites visités s’appliquent également.</p><p>Les suggestions au fil de la saisie ne déclenchent pas d’appel payant. Le nombre total de pages correspondant à une requête n’est pas inventé : seuls les résultats effectivement reçus sont affichés.</p><a href="./">← Revenir à la recherche</a></main>'
    elif not query:
        hint=('Résultats Web fournis par Brave' if stats.get('configured') else 'Le serveur de recherche Web attend sa configuration') if remote else str(stats['pages'])+' pages dans l’index Nova local'
        content='<main class="hero"><span class="mark">'+MARK+'</span><h1>Nova Search</h1><p>Votre recherche, votre espace.</p>'+form()+'<div class="hint">'+hint+'</div></main>'
    else:
        filters=''
        for key,label in [('all','Tout'),('guides','Guides'),('communauté','Communautés')]:
            if remote and key!='all':continue
            filters+='<a '+('class="active" ' if kind==key else '')+'href="search?'+e(urlencode({'q':query,'kind':key,'order':order}),quote=True)+'">'+label+'</a>'
        if not remote:filters+='<select aria-label="Trier les résultats"><option value="relevance">Pertinence</option><option value="recent"'+(' selected' if order=='recent' else '')+'>Ajout récent</option></select>'
        results=''
        for r in found['results']:
            host=urlsplit(r['url']).hostname or '';source='Brave' if r['source']=='brave' else 'NovaBot' if r['source']=='exploration' else 'Catalogue initial'
            results+='<article class="result"><div class="source"><span class="initial">'+e(host.removeprefix('www.')[:1].upper())+'</span><div>'+e(host)+'<small>'+source+'</small><div class="url">'+e(r['url'])+'</div></div></div><h2><a rel="noreferrer" href="'+e(r['url'],quote=True)+'">'+e(r['title'])+'</a></h2><p>'+e(r['description'])+'</p></article>'
        if not results:results='<div class="empty"><h2>Aucun résultat dans notre index pour cette recherche.</h2><p>Essayez des mots plus courts ou un autre sujet. L’index Nova est encore en construction.</p></div>'
        if remote and not results:results='<div class="empty"><h2>'+('Recherche momentanément indisponible' if found.get('error') else 'Aucun résultat Web pour cette recherche.')+'</h2><p>'+e(found.get('error','Essayez d’autres mots-clés.'))+'</p></div>'
        pages=''
        for offset,label in [(-1,'← Précédent'),(1,'Suivant →')]:
            n=found['page']+offset
            has_next=found.get('has_more',False) if remote else n<=((found['total']+9)//10)
            if n>=1 and (offset<0 or has_next):pages+='<a href="search?'+e(urlencode({'q':query,'kind':kind,'order':order,'page':n}),quote=True)+'">'+label+'</a>'
        summary='Résultats Web · fournis par Brave' if remote else str(found['total'])+' résultat(s) dans l’index Nova · '+str(found['milliseconds'])+' ms'
        content='<main><nav class="filters">'+filters+'</nav><p class="summary">'+summary+'</p><section class="results">'+results+'<nav class="pages">'+pages+'</nav></section></main>'
    footer='Résultats Web fournis par Brave' if remote else str(stats['pages'])+' pages, dont '+str(stats['crawled'])+' explorées'
    if remote:footer+=' · Google prend le relais si le quota est atteint'
    return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(query+' — ' if query else '')+'Nova Search</title><link rel="stylesheet" href="style.css"><link rel="icon" href="data:,"></head><body>'+header+content+'<footer><span>Nova Search · '+footer+'</span><span><a href="about">Fonctionnement et confidentialité</a></span></footer><script src="app.js" defer></script></body></html>'
